import sys
import math
MAXNUM = math.inf
MINNUM = -1 * math.inf
ASCIILOWER = 97
ASCIIUPPER = 65

def getInt():
	return int(sys.stdin.readline().rstrip())

def getInts():
	return map(int, sys.stdin.readline().rstrip().split(' '))

def getString():
	return sys.stdin.readline().rstrip()

def printOutput(ans):
	sys.stdout.write()
	pass

def solve(parsedprog):
	stack = []
	for op in parsedprog:
		if op and op[0] in ('try', 'throw'):
			stack.append(op)
		elif op and op[0] == 'catch':
			k = stack.pop()
			if k[0] == 'throw':
				if op[1] == k[1]:
					return op[2]
				else:
					stack.append(k)
	return 'Unhandled Exception'

def multisplit(string):
	parsedstring = []
	curstring = []
	insidequotes = False
	for i in string:
		if insidequotes:
			if i == '"':
				insidequotes = False
				parsedstring.append(''.join(curstring))
				curstring = []
			else:
				curstring.append(i)
		elif i in ('(', ')', ',', ' '):
			if curstring:
				parsedstring.append(''.join(curstring))
			curstring = []
		elif i == '"':
			insidequotes = True
			if curstring:
				parsedstring.append(''.join(curstring))
			curstring = []
		else:
			curstring.append(i)
	if curstring:
		parsedstring.append(''.join(curstring))
	return parsedstring

def readinput():
	proglen = getInt()
	parsedprog = []
	for _ in range(proglen):
		parsedprog.append(multisplit(getString()))
	print(solve(parsedprog))
